@@ -0,0 +1,46 @@
+use axum::body::Bytes;
+use gigastt_core::inference::audio::{replay_pilot_packets, replay_pilot_windows};
+use std::{fs, hint::black_box, path::Path, time::Instant};
+
+fn cpu_ticks() -> u64 {
+    let stat = fs::read_to_string("/proc/self/stat").unwrap();
+    let mut cols = stat.rsplit_once(')').unwrap().1.split_whitespace().skip(11);
+    cols.next().unwrap().parse::<u64>().unwrap() + cols.next().unwrap().parse::<u64>().unwrap()
+}
+
+fn main() {
+    let args: Vec<_> = std::env::args().collect();
+    let dir = Path::new(&args[1]);
+    let windows = match args[2].as_str() {
+        "input" => true,
+        "packets" => false,
+        s => panic!("invalid mode {s}"),
+    };
+    let mut inputs = Vec::new();
+    let mut packets = Vec::new();
+    for i in 0..15 {
+        if windows {
+            inputs.push(Bytes::from(fs::read(dir.join(format!("golos_{i:02}.opus"))).unwrap()));
+        } else {
+            let file = fs::read(dir.join(format!("golos_{i:02}"))).unwrap();
+            let mut rem = &file[..];
+            let mut clip = Vec::new();
+            while !rem.is_empty() {
+                let n = u32::from_be_bytes(rem[..4].try_into().unwrap()) as usize;
+                clip.push(rem[4..4+n].to_vec());
+                rem = &rem[4+n..];
+            }
+            packets.push(clip);
+        }
+    }
+    let run = || {
+        for input in &inputs { black_box(replay_pilot_windows(input.clone()).unwrap()); }
+        for clip in &packets { replay_pilot_packets(clip).unwrap(); }
+    };
+    run();
+    let before = cpu_ticks();
+    let clock = Instant::now();
+    for _ in 0..24 { run(); }
+    let wall_ns = clock.elapsed().as_nanos();
+    println!("{} {}", cpu_ticks() - before, wall_ns);
+}

